(()=>{
'use strict';
const A=window.G||{}, app=document.querySelector('#app');
let s={};try{s=JSON.parse(localStorage.getItem('90dq')||'{}')}catch(e){s={}};
const defaults={name:'',ac:'#18d47a',bg:'#07111f',sound:true,anim:true,diff:'متوسط',rounds:10,seconds:20,questionPoints:120,budget:750,buyLimit:6,xp:0,best:0,games:0,streak:0,totalAnswered:0,totalCorrect:0,budgetWins:0,whoWins:0,daily:{date:'',answered:0,correct:0,games:0}};
s={...defaults,...s};
let state={mode:'',score:0,q:0,rounds:10,timer:null,locked:false,current:null,streak:0,diff:s.diff,used:new Set(),local:null,multiplier:1,jokers:{fifty:1,double:1,skip:1},auction:null,who:null};
const save=()=>{try{localStorage.setItem('90dq',JSON.stringify(s))}catch(e){console.warn('تعذر حفظ التقدم محليًا',e)}};
const level=()=>Math.floor((s.xp||0)/500)+1;
const diffCfg={'مبتدئ':{seconds:35,points:80},'سهل':{seconds:25,points:100},'متوسط':{seconds:20,points:120},'صعب':{seconds:15,points:160},'أسطوري':{seconds:10,points:220}};
const cfg=()=>diffCfg[s.diff]||diffCfg['متوسط'];
const basePoints=()=>Math.max(10,Number(s.questionPoints)||cfg().points);
function dailyState(){const d=new Date().toISOString().slice(0,10);if(!s.daily||s.daily.date!==d)s.daily={date:d,answered:0,correct:0,games:0};return s.daily}
function trackAnswer(ok){const d=dailyState();d.answered++;if(ok)d.correct++;}
function trackGame(){dailyState().games++;}
const pick=a=>a[Math.floor(Math.random()*a.length)];
const shuffle=a=>[...a].sort(()=>Math.random()-.5);
const unique=a=>[...new Set(a)];
function cleanQuestion(q){const raw=Array.isArray(q?.[1])?q[1]:[];const answer=raw[q[2]];const opts=unique(raw.filter(x=>x!==undefined&&x!==null&&String(x).trim()!==''));if(answer!==undefined&&!opts.includes(answer))opts.push(answer);return {text:q[0],opts:shuffle(opts),correctText:answer};}
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function applyTheme(){document.documentElement.style.setProperty('--a',s.ac);document.documentElement.style.setProperty('--bg',s.bg);document.documentElement.style.fontSize=s.font||'16px';const b=document.querySelector('#levelBadge');if(b)b.textContent=`Lv.${level()}`}
applyTheme();
function nav(show){const n=document.querySelector('#mainNav');if(n)n.classList.toggle('nav-hidden',!show)}
function head(title,sub=''){return `<div class="row"><button class="back" onclick="goHome()">←</button><div><h2>${title}</h2><span class="muted">${sub}</span></div></div>`}
function goHome(){clearTimer();home()} window.goHome=goHome;
let audioCtx=null;
function audio(){if(!s.sound)return null;try{audioCtx=audioCtx||(new(window.AudioContext||window.webkitAudioContext)());if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}catch(e){return null}}
function tone(freq,dur=.08,type='sine',gain=.035,delay=0){const c=audio();if(!c)return;setTimeout(()=>{const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(gain,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+dur);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+dur)},delay)}
function uiClick(){tone(430,.045,'square',.018)}
function correctSound(){tone(660,.08,'triangle',.045);tone(880,.11,'triangle',.035,70);tone(1040,.13,'sine',.025,150)}
function wrongSound(){tone(210,.16,'sawtooth',.05);tone(130,.22,'sawtooth',.035,100)}
function timeSound(){tone(180,.12,'square',.04);tone(120,.18,'square',.03,120)}
document.addEventListener('click',e=>{if(e.target.closest('button'))uiClick()});
function celebration(){if(!s.anim)return;const box=document.createElement('div');box.className='confetti';box.innerHTML=Array.from({length:42},(_,i)=>`<i style="--i:${i}"></i>`).join('');document.body.appendChild(box);setTimeout(()=>box.remove(),1400)}
function clearTimer(){if(state.timer){clearInterval(state.timer);state.timer=null}}
function startTimer(sec,done){clearTimer();let left=Math.max(1,Number(sec)||20);const draw=()=>{const e=document.querySelector('.timer');if(e){e.textContent=left;e.classList.toggle('urgent',left<=3)}};draw();state.timer=setInterval(()=>{left--;draw();if(left<=3&&left>0)timeSound();if(left<=0){clearTimer();done('time')}},1000)}
function setup(m){nav(false);clearTimer();state={mode:m,score:0,q:0,rounds:Number(s.rounds)||10,timer:null,locked:false,current:null,streak:0,diff:s.diff||'متوسط',used:new Set(),local:null,multiplier:1,jokers:{fifty:1,double:1,skip:1},auction:null,who:null}}
function markUsed(key,item,arr){const i=arr.indexOf(item);if(i<0)return;state.used.add(`${key}:${i}`)}
function nextUnique(key,arr){if(!arr?.length)return null;let fresh=arr.filter((_,i)=>!state.used.has(`${key}:${i}`));if(!fresh.length){for(const k of [...state.used])if(k.startsWith(key+':'))state.used.delete(k);fresh=arr}const item=pick(fresh);markUsed(key,item,arr);return item}
function finish(msg='انتهت الجولة'){clearTimer();s.games++;trackGame();s.best=Math.max(s.best,state.score);s.xp+=state.score;save();applyTheme();celebration();app.innerHTML=`<div class="result"><div style="font-size:70px">${state.score>=700?'🏆':'⚽'}</div><h1>${msg}</h1><div class="score">${state.score}</div><p class="muted">+${state.score} XP · المستوى ${level()} · أفضل نتيجة ${s.best}</p><div class="notice">🔥 سلسلة الجولة: ${state.streak} · 🎯 الدقة العامة: ${s.totalAnswered?Math.round(s.totalCorrect/s.totalAnswered*100):0}%</div><button class="primary" onclick="start('${state.mode}')">إعادة اللعب 🔁</button> <button onclick="modes()" class="secondary">كل التحديات ⚽</button></div>`}
function feedback(correct,chosen,answer,next,points=0,extra=''){state.locked=true;document.querySelectorAll('.ans').forEach(b=>b.disabled=true);const btns=[...document.querySelectorAll('.ans')];if(btns[chosen])btns[chosen].classList.add(correct?'ok':'no');if(btns[answer])btns[answer].classList.add('ok');correct?correctSound():wrongSound();if(correct)celebration();const box=document.querySelector('.feedback');if(box){box.className='feedback '+(correct?'good':'bad');box.innerHTML=correct?`🎉 إجابة صحيحة! <b>+${points}</b> ${extra}`:`😅 إجابة غير صحيحة<br>الإجابة الصحيحة: <b>${btns[answer]?.textContent||'—'}</b> ${extra}`}setTimeout(()=>{state.locked=false;try{next()}catch(e){console.error(e);finish('حدث خطأ وتم حفظ نتيجتك')}} ,correct?260:1150)}
function answer(i){if(state.locked||!state.current)return;const {correct,next,points=100}=state.current;const ok=i===correct,earned=Math.round(points*(state.multiplier||1));state.lastAnswerOk=ok;s.totalAnswered++;trackAnswer(ok);if(ok){state.score+=earned;state.streak++;s.streak=Math.max(s.streak||0,state.streak);s.totalCorrect++;if(state.mode==='who')s.whoWins=(s.whoWins||0)+1;}else state.streak=0;save();clearTimer();state.multiplier=1;feedback(ok,i,correct,next,earned,ok?'🔥 سلسلة '+state.streak:'')}
window.answer=answer;
window.useFifty=()=>{if(state.locked||!state.current||!state.jokers.fifty)return;state.jokers.fifty=0;const bad=[...document.querySelectorAll('.ans')].map((b,i)=>i).filter(i=>i!==state.current.correct);shuffle(bad).slice(0,2).forEach(i=>{const b=document.querySelectorAll('.ans')[i];if(b){b.disabled=true;b.classList.add('faded')}});tone(520,.07,'triangle',.03)};
window.useDouble=()=>{if(state.locked||!state.jokers.double)return;state.jokers.double=0;state.multiplier=2;document.querySelectorAll('.powerbar button')[1]?.classList.add('used');tone(720,.08,'triangle',.03)};
window.useSkip=()=>{if(state.locked||!state.current||!state.jokers.skip)return;state.jokers.skip=0;clearTimer();state.locked=true;tone(360,.08,'sine',.025);setTimeout(()=>{state.locked=false;state.multiplier=1;state.current.next()},150)};
function renderAnswers(opts,correct){state.locked=false;return `<div class="answers">${opts.map((x,i)=>`<button class="ans" onclick="answer(${i})">${x}</button>`).join('')}</div><div class="powerbar"><button onclick="useFifty()" ${state.jokers.fifty?'':'disabled'}>✂️ 50/50</button><button onclick="useDouble()" ${state.jokers.double?'':'disabled'}>×2 مضاعفة</button><button onclick="useSkip()" ${state.jokers.skip?'':'disabled'}>⏭️ تخطي</button></div><div class="feedback" aria-live="polite"></div>`}
function questionQuiz(){state.q++;if(state.q>state.rounds)return finish();const q=nextUnique('q',A.q||[]);if(!q)return finish();const points=basePoints();state.current={correct:q[2],next:questionQuiz,points};app.innerHTML=`${head('🧠 كويز 90',`السؤال ${state.q}/${state.rounds} · ${state.diff} · موسم ${A.meta?.season||'2026/27'}`)}<div class="qbox"><span class="timer">${cfg().seconds}</span><div class="question-no">${state.q}</div><div class="emoji-line">🧠 ⚽ 🔥</div><h2>${q[0]}</h2>${renderAnswers(q[1],q[2])}</div>`;startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;timeSound();feedback(false,-1,q[2],questionQuiz,points,'⏰ انتهى الوقت')})}
const playerAliases={'محمد صلاح':'Mohamed Salah','كريستيانو رونالدو':'Cristiano Ronaldo','ليونيل ميسي':'Lionel Messi','كيليان مبابي':'Kylian Mbappé','إيرلينغ هالاند':'Erling Haaland','جود بيلينغهام':'Jude Bellingham','فينيسيوس جونيور':'Vinícius Júnior','لامين يامال':'Lamine Yamal','هاري كين':'Harry Kane','روبرت ليفاندوفسكي':'Robert Lewandowski','نيمار':'Neymar','لوكا مودريتش':'Luka Modrić','سيرخيو راموس':'Sergio Ramos','مانويل نوير':'Manuel Neuer','أنطوان غريزمان':'Antoine Griezmann','رونالدينيو':'Ronaldinho','رونالدو نازاريو':'Ronaldo (Brazilian footballer)','زين الدين زيدان':'Zinedine Zidane','تييري هنري':'Thierry Henry','ديفيد بيكهام':'David Beckham','واين روني':'Wayne Rooney','جانلويجي بوفون':'Gianluigi Buffon','باولو مالديني':'Paolo Maldini','كاكا':'Kaká','أندريا بيرلو':'Andrea Pirlo','تشافي':'Xavi','إنييستا':'Andrés Iniesta','لويس سواريز':'Luis Suárez','كريم بنزيما':'Karim Benzema','رياض محرز':'Riyad Mahrez','ساديو ماني':'Sadio Mané','أشرف حكيمي':'Achraf Hakimi','سون هيونغ مين':'Son Heung-min','برونو فيرنانديز':'Bruno Fernandes','فيرجيل فان دايك':'Virgil van Dijk','رودري':'Rodri (footballer, born 1996)','بوكايو ساكا':'Bukayo Saka','كول بالمر':'Cole Palmer','لاوتارو مارتينيز':'Lautaro Martínez','جمال موسيالا':'Jamal Musiala','توماس مولر':'Thomas Müller','فيل فودين':'Phil Foden','كيفن دي بروين':'Kevin De Bruyne','ديدييه دروغبا':'Didier Drogba'};
const clubAliases={'ريال مدريد':'Real Madrid CF','برشلونة':'FC Barcelona','مانشستر سيتي':'Manchester City F.C.','مانشستر يونايتد':'Manchester United F.C.','ليفربول':'Liverpool F.C.','أرسنال':'Arsenal F.C.','تشيلسي':'Chelsea F.C.','باريس سان جيرمان':'Paris Saint-Germain F.C.','بايرن ميونخ':'FC Bayern Munich','بوروسيا دورتموند':'Borussia Dortmund','إنتر ميلان':'Inter Milan','إنتر':'Inter Milan','ميلان':'AC Milan','يوفنتوس':'Juventus FC','أتلتيكو مدريد':'Atlético Madrid','النصر':'Al Nassr FC','الهلال':'Al Hilal SFC','الأهلي':'Al-Ahli Saudi FC','الاتحاد':'Al-Ittihad Club (Jeddah)','سانتوس':'Santos FC','إنتر ميامي':'Inter Miami CF','توتنهام':'Tottenham Hotspur F.C.','فانكوفر':'Vancouver Whitecaps FC','لوس أنجلوس':'Los Angeles FC'};
function fallbackVisual(target,name,kind){if(!target)return;target.style.display='none';const box=target.parentElement;if(!box)return;const f=box.querySelector('.media-fallback,.logo-fallback');if(f){f.style.display='flex';f.textContent=kind==='club'?String(name).split(/\s+/).map(x=>x[0]).slice(0,3).join(''):String(name).split(/\s+/).map(x=>x[0]).slice(0,2).join('')}}
async function wikiImage(name,target,kind='player'){
 const alias=(kind==='club'?clubAliases[name]:playerAliases[name])||name;
 const key=`img6:${kind}:${alias}`;
 let cached=null;try{cached=localStorage.getItem(key)}catch(e){}
 const markLoaded=()=>{target.style.display='block';target.closest('.media-box,.club-tile,.logo-wrap')?.classList.add('loaded')};
 const fail=()=>fallbackVisual(target,name,kind);
 if(cached){target.onload=markLoaded;target.onerror=fail;target.src=cached;return}
 const queries=kind==='club' ? [alias+' football club',name+' football club',alias] : [alias+' footballer',name+' footballer',alias];
 const langs=kind==='club'?['en','ar']:['en','ar'];
 for(const lang of langs){
  for(const title of queries){
   try{
    let api=`https://${lang}.wikipedia.org/w/api.php?action=query&prop=pageimages&format=json&pithumbsize=${kind==='club'?500:1000}&redirects=1&titles=${encodeURIComponent(title)}&origin=*`;
    let r=await fetch(api); if(r.ok){let d=await r.json(),pg=Object.values(d?.query?.pages||{})[0],src=pg?.thumbnail?.source;if(src){try{localStorage.setItem(key,src)}catch(e){}target.onload=markLoaded;target.onerror=fail;target.src=src;return}}
    api=`https://${lang}.wikipedia.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(title)}&gsrlimit=3&prop=pageimages&piprop=thumbnail&pithumbsize=${kind==='club'?500:1000}&format=json&origin=*`;
    r=await fetch(api);if(r.ok){let d=await r.json(),pages=Object.values(d?.query?.pages||{}).filter(x=>x.thumbnail?.source);if(pages.length){let src=pages[0].thumbnail.source;try{localStorage.setItem(key,src)}catch(e){}target.onload=markLoaded;target.onerror=fail;target.src=src;return}}
   }catch(e){}
  }
 }
 fail(target,name,kind);
}
function mediaCard(name,caption,kind='player'){return `<div class="media-box"><img alt="صورة لاعب" data-media="${esc(name)}" onerror="this.style.display='none'"><div class="media-fallback">${kind==='club'?'🏟️':'👤'}</div></div><p class="muted">${caption}</p>`}
function playerQuestion(){state.q++;if(state.q>state.rounds)return finish();const p=nextUnique('p',A.players||[]);const opts=shuffle(unique([p[0],...shuffle((A.players||[]).filter(x=>x[0]!==p[0]).map(x=>x[0])).slice(0,3)])),correct=opts.indexOf(p[0]),points=cfg().points+30;state.current={correct,next:playerQuestion,points};app.innerHTML=`${head('👤 خمن اللاعب',`السؤال ${state.q}/${state.rounds}`)}<div class="qbox"><span class="timer">${cfg().seconds}</span>${mediaCard(p[0],'صورة اللاعب كاملة عند توفر الإنترنت')}<h2>من اللاعب؟</h2><p class="muted">🔎 راقب الصورة واختر الاسم الصحيح</p>${renderAnswers(opts,correct)}</div>`;const im=app.querySelector('img[data-media]');if(im)wikiImage(p[0],im);startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;timeSound();feedback(false,-1,correct,playerQuestion,points,'⏰ انتهى الوقت')})}
function attrQuestion(kind,title,points=130){state.q++;if(state.q>state.rounds)return finish();const p=nextUnique('a',A.players||[]);const vals=shuffle(unique((A.players||[]).filter(x=>x[0]!==p[0]).map(x=>x[kind]).filter(Boolean))).slice(0,3);const opts=shuffle(unique([p[kind],...vals])).slice(0,4),correct=opts.indexOf(p[kind]);state.current={correct,next:()=>attrQuestion(kind,title,points),points};app.innerHTML=`${head('🌍 تحدي المعرفة',`السؤال ${state.q}/${state.rounds}`)}<div class="qbox"><span class="timer">${cfg().seconds}</span>${mediaCard(p[0],'استخدم الصورة + المعلومات الظاهرة')}<h2>${title}</h2><p class="muted">🔎 لا يوجد اسم اللاعب على الشاشة</p>${renderAnswers(opts,correct)}</div>`;const im=app.querySelector('img[data-media]');if(im)wikiImage(p[0],im);startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;timeSound();feedback(false,-1,correct,()=>attrQuestion(kind,title,points),points,'⏰ انتهى الوقت')})}
function careerQuestion(){state.q++;if(state.q>state.rounds)return finish();const list=(A.players||[]).filter(x=>x[5]?.length>=3),p=nextUnique('c',list),shown=p[5].slice().reverse().slice(0,Math.min(6,p[5].length));const opts=shuffle(unique([p[0],...shuffle((A.players||[]).filter(x=>x[0]!==p[0]).map(x=>x[0])).slice(0,3)])),correct=opts.indexOf(p[0]),points=cfg().points+70;state.current={correct,next:careerQuestion,points};app.innerHTML=`${head('🧭 مسار اللاعب',`السؤال ${state.q}/${state.rounds}`)}<div class="qbox"><span class="timer">${(s.seconds||cfg().seconds)+5}</span><h2>من صاحب هذه المسيرة؟</h2><div class="career">${shown.map((x,i)=>`<span>${i+1} · ${x}</span>`).join('')}</div>${renderAnswers(opts,correct)}</div>`;startTimer((s.seconds||cfg().seconds)+5,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;timeSound();feedback(false,-1,correct,careerQuestion,points,'⏰ انتهى الوقت')})}
function transferMode(exact=false){state.q++;if(state.q>state.rounds)return finish('انتهى تحدي سوق الانتقالات');const t=nextUnique('tr',A.transfers||[]);if(!t)return finish();const actual=Number(t.fee||0);let opts,correct;if(exact){const vals=unique([actual,...shuffle((A.transfers||[]).map(x=>Number(x.fee||0)).filter(x=>x!==actual)).slice(0,3)]);opts=shuffle(vals.map(v=>`€${v}M`));correct=opts.indexOf(`€${actual}M`)}else{const ranges=['أقل من €20M','€20M–€49M','€50M–€89M','€90M فأكثر'];const bucket=actual<20?ranges[0]:actual<50?ranges[1]:actual<90?ranges[2]:ranges[3];opts=shuffle(ranges);correct=opts.indexOf(bucket)}const points=basePoints()+(exact?130:100);state.current={correct,next:()=>transferMode(exact),points};app.innerHTML=`${head(exact?'💸 خمن القيمة الأقرب':'💰 خمن سعر الانتقال',`السؤال ${state.q}/${state.rounds} · ${A.meta?.season||'2026/27'}`)}<div class="qbox transfer-card"><span class="timer">${s.seconds||cfg().seconds}</span><div class="transfer-line"><div class="big-avatar">💶</div><div><h2>${t.player}</h2><p>${t.from} <b>→</b> ${t.to}</p><span class="tag">${t.date}</span></div></div><h3>${exact?'ما القيمة الأقرب للصفقة؟':'في أي نطاق كانت قيمة الصفقة؟'}</h3>${renderAnswers(opts,correct)}</div>`;startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;timeSound();feedback(false,-1,correct,()=>transferMode(exact),points,'⏰ انتهى الوقت')})}
function higher(){state.q++;if(state.q>state.rounds)return finish();const [a,b]=shuffle(A.players||[]).slice(0,2);if(!a||!b)return finish();const opts=['الأول','الثاني'];const correct=(Number(a[4])<=Number(b[4]))?0:1;const points=basePoints();state.current={correct,next:higher,points};app.innerHTML=`${head('📈 أعلى / أقل',`السؤال ${state.q}/${state.rounds}`)}<div class="qbox"><span class="timer">${cfg().seconds}</span><h2>من اللاعب الأكبر سنًا؟</h2><div class="compare"><div>👤<b>${a[0]}</b><small>${a[4]}</small></div><strong>VS</strong><div>👤<b>${b[0]}</b><small>${b[4]}</small></div></div>${renderAnswers(opts,correct)}</div>`;startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;timeSound();feedback(false,-1,correct,higher,points,'⏰ انتهى الوقت')})}
function pitchGrid(items,type='flags'){const pos=['gk','lb','cb1','cb2','rb','cm1','cm2','lw','am','rw','st'];return `<div class="xi-pitch">${items.slice(0,11).map((it,i)=>`<div class="xi ${pos[i]}">${type==='flags'?`<span class="xi-flag">${flag(it.nat)}</span><small>${it.nat}</small>`:`<span class="logo-wrap"><img data-club="${esc(it.club)}" alt="${esc(it.club)}"><i class="logo-fallback">${esc(it.club).slice(0,2)}</i></span><small>${it.club}</small>`}</div>`).join('')}</div>`}
function lineup(){state.q++;if(state.q>state.rounds)return finish('اكتمل تحدي التشكيلات');const list=A.clubLineups||[];const t=nextUnique('clubXI',list);if(!t)return finish();const wrong=shuffle(list.filter(x=>x.team!==t.team).map(x=>x.team)).slice(0,3),opts=shuffle([t.team,...wrong]),correct=opts.indexOf(t.team),points=cfg().points+180;state.current={correct,next:lineup,points};app.innerHTML=`${head('📋 خمن الفريق من التشكيلة',`السؤال ${state.q}/${state.rounds} · 11 لاعبًا`)}<div class="qbox formation"><span class="timer">${s.seconds||cfg().seconds}</span><h2>من خلال جنسيات لاعبي التشكيلة… ما الفريق؟</h2>${pitchGrid(t.xi,'flags')}<p class="muted">💡 كل دائرة تمثل لاعبًا في مركزه، وتظهر جنسيته فقط.</p>${renderAnswers(opts,correct)}</div>`;startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;feedback(false,-1,correct,lineup,points,'⏰ انتهى الوقت')})}
function teamFromNationalities(){return lineup()}
function nationalFromClubs(){state.q++;if(state.q>state.rounds)return finish('اكتمل تحدي المنتخبات');const list=A.nationalLineups||[];const t=nextUnique('natXI',list);if(!t)return finish();const wrong=shuffle(list.filter(x=>x.team!==t.team).map(x=>x.team)).slice(0,3),opts=shuffle([t.team,...wrong]),correct=opts.indexOf(t.team),points=cfg().points+200;state.current={correct,next:nationalFromClubs,points};app.innerHTML=`${head('🛡️ خمن المنتخب من شعارات الأندية',`السؤال ${state.q}/${state.rounds} · 11 لاعبًا`)}<div class="qbox formation"><span class="timer">${s.seconds||cfg().seconds}</span><h2>هذه شعارات أندية لاعبي التشكيلة… ما المنتخب؟</h2>${pitchGrid(t.xi,'clubs')}<p class="muted">🔎 الاسم تحت الشعار موجود كاحتياط لو تعذر تحميل الشعار.</p>${renderAnswers(opts,correct)}</div>`;app.querySelectorAll('img[data-club]').forEach(im=>clubBadge(im.dataset.club,im));startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;feedback(false,-1,correct,nationalFromClubs,points,'⏰ انتهى الوقت')})}
function clubBadge(name,target){wikiImage(name,target,'club')}
function crossQuestion(){state.q++;if(state.q>state.rounds)return finish();const p=nextUnique('cross',A.players||[]);if(!p)return finish();const yes=pick(p[5]||[])||p[2],all=unique((A.players||[]).flatMap(x=>x[5]||[])),no=pick(all.filter(c=>!(p[5]||[]).includes(c))),target=Math.random()>.5?yes:no,truth=(p[5]||[]).includes(target),opts=['نعم','لا'],correct=truth?0:1,points=cfg().points+40;state.current={correct,next:crossQuestion,points};app.innerHTML=`${head('✖️ هل لعب هنا؟',`السؤال ${state.q}/${state.rounds}`)}<div class="qbox"><span class="timer">${s.seconds||cfg().seconds}</span><h2>هل لعب ${p[0]} مع ${target}؟</h2>${renderAnswers(opts,correct)}</div>`;startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;save();feedback(false,-1,correct,crossQuestion,points,'⏰ انتهى الوقت')})}
function blitz(){state.q=0;state.score=0;state.mode='blitz';const end=Date.now()+60000;function go(){if(Date.now()>=end)return finish('انتهى Blitz');state.q++;const q=nextUnique('blitz',A.q||[]);if(!q)return finish('انتهت الأسئلة المتاحة');state.current={correct:q[2],next:go,points:70};app.innerHTML=`${head('⚡ Blitz 60',`إجابات: ${state.q-1}`)}<div class="qbox"><span class="timer">${Math.max(0,Math.ceil((end-Date.now())/1000))}</span><div class="emoji-line">⚡🔥⚡</div><h2>${q[0]}</h2>${renderAnswers(q[1],q[2])}</div>`}go();state.timer=setInterval(()=>{const e=document.querySelector('.timer');if(e)e.textContent=Math.max(0,Math.ceil((end-Date.now())/1000));if(Date.now()>=end){clearTimer();finish('انتهى Blitz')}},250)}
function survival(){state.q=0;state.score=0;state.mode='survival';function go(){state.q++;const q=nextUnique('survival',A.q||[]);if(!q)return finish('أكملت بنك الأسئلة');state.current={correct:q[2],next:go,points:100+state.q*5};app.innerHTML=`${head('🔥 البقاء','خطأ واحد ينهي السلسلة')}<div class="qbox"><div class="tag">🔥 سلسلة ${Math.max(0,state.q-1)}</div><h2>${q[0]}</h2>${renderAnswers(q[1],q[2])}</div>`}state.survivalNext=go;go()}
function face(){state.q++;if(state.q>state.rounds)return finish();const p=nextUnique('face',A.players||[]),opts=shuffle(unique([p[0],...shuffle((A.players||[]).filter(x=>x[0]!==p[0]).map(x=>x[0])).slice(0,3)])),correct=opts.indexOf(p[0]),points=cfg().points+50;state.current={correct,next:face,points};app.innerHTML=`${head('🖼️ خمن الصورة','صور اللاعبين كاملة عند الاتصال')}<div class="qbox"><span class="timer">${s.seconds||cfg().seconds}</span>${mediaCard(p[0],'الصورة تُجلب تلقائيًا عند توفر الاتصال')}<h2>من هذا اللاعب؟</h2>${renderAnswers(opts,correct)}</div>`;const im=app.querySelector('img[data-media]');if(im)wikiImage(p[0],im);startTimer(s.seconds||cfg().seconds,()=>{s.totalAnswered++;trackAnswer(false);state.streak=0;timeSound();feedback(false,-1,correct,face,points,'⏰ انتهى الوقت')})}
function local(){clearTimer();nav(false);app.innerHTML=`${head('👥 اللعب الجماعي','2–8 لاعبين · بدون نوافذ مزعجة · مناسب للموبايل')}<div class="setup-card"><div class="notice">📱 أدخل أسماء اللاعبين، ثم ابدأ. بعد كل إجابة سيظهر زر تمرير الجهاز للاعب التالي.</div><label class="setting">اللاعبون (اسم في كل خانة)<input id="lp1" class="input" value="عم عمرو" placeholder="اللاعب 1"><input id="lp2" class="input" value="اللاعب 2" placeholder="اللاعب 2"><input id="lp3" class="input" placeholder="اللاعب 3 (اختياري)"><input id="lp4" class="input" placeholder="اللاعب 4 (اختياري)"><input id="lp5" class="input" placeholder="اللاعب 5 (اختياري)"><input id="lp6" class="input" placeholder="اللاعب 6 (اختياري)"><input id="lp7" class="input" placeholder="اللاعب 7 (اختياري)"><input id="lp8" class="input" placeholder="اللاعب 8 (اختياري)"></label><div class="setup-actions"><button class="primary" onclick="startLocalGame()">🚀 ابدأ اللعب الجماعي</button><button class="secondary" onclick="modes()">رجوع</button></div></div>`}
window.startLocalGame=()=>{const ps=unique([1,2,3,4,5,6,7,8].map(i=>document.querySelector('#lp'+i)?.value.trim()).filter(Boolean)).slice(0,8);if(ps.length<2){alert('أدخل اسم لاعبين مختلفين على الأقل');return}state.local={players:ps,scores:ps.map(()=>0),turn:0,round:1,total:Math.min(Number(s.rounds)||5,20),answered:0,correct:0};state.score=0;save();localPassScreen('ابدأوا!','مرر الجهاز إلى أول لاعب ثم اضغط جاهز 👇')};
function localPassScreen(title='مرر الجهاز',message='مرر الجهاز للاعب التالي فقط، ثم اضغط جاهز حتى لا يرى إجابة اللاعب السابق.'){
 clearTimer();const L=state.local;if(!L)return;const next=L.players[L.turn];app.innerHTML=`${head('👥 جماعي محلي',`الجولة ${L.round}/${L.total} · ${L.answered}/${L.total*L.players.length} إجابة`)}<div class="pass-screen"><div class="pass-icon">📱</div><h1>${esc(title)}</h1><p>${esc(message)}</p><div class="notice">🎮 الدور الآن: <b>${esc(next)}</b></div><div class="local-score">${L.players.map((p,i)=>`<div class="${i===L.turn?'active-player':''}"><b>${esc(p)}</b><br>⭐ ${L.scores[i]}</div>`).join('')}</div><button class="primary" onclick="localRound()">أنا جاهز — ابدأ السؤال ▶️</button></div>`}
function localRound(){clearTimer();state.locked=false;const L=state.local;if(!L)return;if(L.round>L.total)return localFinish();const player=L.players[L.turn],q=nextUnique('local',A.q||[]);if(!q)return localFinish();const cq=cleanQuestion(q);if(cq.opts.length<2)return localRound();const correct=cq.opts.indexOf(cq.correctText);state.mode='local';state.current={correct,next:()=>{},points:basePoints()};app.innerHTML=`${head('👥 جماعي محلي',`الجولة ${L.round}/${L.total} · إجابة اللاعب ${L.turn+1}/${L.players.length}`)}<div class="notice">🎮 الدور الآن: <b>${esc(player)}</b> · لا تظهر أي نتيجة حتى تنتهي الإجابة</div><div class="local-score">${L.players.map((p,i)=>`<div class="${i===L.turn?'active-player':''}"><b>${esc(p)}</b><br>⭐ ${L.scores[i]}</div>`).join('')}</div><div class="qbox"><span class="timer">${s.seconds||cfg().seconds}</span><h2>${esc(cq.text)}</h2><div class="answers">${cq.opts.map((x,i)=>`<button class="ans" onclick="localAnswer(${i})">${esc(x)}</button>`).join('')}</div><div class="feedback"></div></div>`;startTimer(s.seconds||cfg().seconds,()=>localAnswer(-1,true))}
function localAnswer(i,timedOut=false){if(state.locked)return;const L=state.local,q=state.current;if(!L||!q)return;clearTimer();const ok=!timedOut&&i===q.correct;state.locked=true;document.querySelectorAll('.ans').forEach(b=>b.disabled=true);const btns=[...document.querySelectorAll('.ans')];if(btns[i])btns[i].classList.add(ok?'ok':'no');if(btns[q.correct])btns[q.correct].classList.add('ok');ok?correctSound():wrongSound();L.answered++;s.totalAnswered++;trackAnswer(ok);if(ok){L.scores[L.turn]+=q.points;state.score+=q.points;L.correct++;s.totalCorrect++;s.xp+=q.points}state.streak=ok?(state.streak+1):0;save();const box=document.querySelector('.feedback');if(box){box.className='feedback '+(ok?'good':'bad');box.innerHTML=ok?`🎉 ${esc(L.players[L.turn])} إجابة صحيحة! <b>+${q.points}</b>`:`❌ ${timedOut?'انتهى الوقت! ':'إجابة غير صحيحة. '}الصحيح: <b>${btns[q.correct]?.textContent||'—'}</b>`}setTimeout(()=>{L.turn=(L.turn+1)%L.players.length;if(L.turn===0)L.round++;if(L.round>L.total){localFinish();return}state.locked=false;localPassScreen('تم تسجيل الإجابة ✅','مرر الجهاز للاعب التالي فقط، ثم اضغط جاهز للجولة التالية.')},ok?500:1300)}
function flag(n){const map={'مصر':'🇪🇬','الأرجنتين':'🇦🇷','البرازيل':'🇧🇷','فرنسا':'🇫🇷','إنجلترا':'🏴','إسبانيا':'🇪🇸','إيطاليا':'🇮🇹','ألمانيا':'🇩🇪','البرتغال':'🇵🇹','هولندا':'🇳🇱','بلجيكا':'🇧🇪','المغرب':'🇲🇦','الجزائر':'🇩🇿','السنغال':'🇸🇳','النرويج':'🇳🇴','السويد':'🇸🇪','أوروغواي':'🇺🇾','الأوروغواي':'🇺🇾','ساحل العاج':'🇨🇮','كولومبيا':'🇨🇴','كوريا الجنوبية':'🇰🇷','كرواتيا':'🇭🇷','المجر':'🇭🇺','بولندا':'🇵🇱','اسكتلندا':'🏴','أوكرانيا':'🇺🇦','كندا':'🇨🇦','الإكوادور':'🇪🇨','سويسرا':'🇨🇭','تركيا':'🇹🇷','أرمينيا':'🇦🇲'};return map[n]||'🌍'}
function localFinish(){clearTimer();const L=state.local,max=Math.max(...L.scores),winner=L.players[L.scores.indexOf(max)],ties=L.players.filter((_,i)=>L.scores[i]===max),acc=L.answered?Math.round(L.correct/L.answered*100):0;s.localGames=(s.localGames||0)+1;trackGame();s.best=Math.max(s.best||0,max);save();celebration();app.innerHTML=`${head('🏆 نهاية اللعب الجماعي','النتيجة النهائية')}<div class="result"><div style="font-size:65px">${ties.length>1?'🤝':'🏆'}</div><h1>${ties.length>1?'تعادل!':'الفائز: '+esc(winner)}</h1><p class="muted">🎯 دقة المجموعة: ${acc}% · ❓ إجابات: ${L.answered}</p><div class="local-score">${L.players.map((p,i)=>`<div class="${L.scores[i]===max?'active-player':''}"><b>${esc(p)}</b><br>⭐ ${L.scores[i]} نقطة</div>`).join('')}</div><button class="primary" onclick="local()">جولة جديدة 🔁</button><button class="secondary" onclick="modes()">كل التحديات ⚽</button></div>`}
function daily(){setup('daily');const day=new Date().toISOString().slice(0,10);const seed=[...day].reduce((a,c)=>a+c.charCodeAt(0),0);let n=seed;const old=Math.random;Math.random=()=>{const x=Math.sin(n++)*10000;return x-Math.floor(x)};questionQuiz();Math.random=old}

function whoAmI(){state.q++;if(state.q>state.rounds)return finish('اكتمل تحدي من أنا؟');const list=(A.who||[]).length?A.who:(A.players||[]).map(p=>({name:p[0],clues:[`أنا من ${p[1]}`,`ألعب في مركز ${p[3]}`,`وُلدت عام ${p[4]}`,`لعبت مع ${(p[5]||[]).slice(-2).join(' و ')}`]}));const item=nextUnique('who',list);if(!item)return finish();const others=shuffle(list.filter(x=>x.name!==item.name)).slice(0,3),opts=shuffle([item.name,...others.map(x=>x.name)]),correct=opts.indexOf(item.name);state.who={item,opts,correct,revealed:1};renderWho()}
function renderWho(){const w=state.who,points=Math.max(40,basePoints()+220-(w.revealed-1)*45);state.current={correct:w.correct,next:whoAmI,points};app.innerHTML=`${head('🕵️ من أنا؟',`السؤال ${state.q}/${state.rounds} · كل تلميح يقلل النقاط`)}<div class="qbox who-card"><span class="tag">💎 ${points} نقطة متاحة</span><div class="silhouette">؟</div><h2>اكتشف اللاعب من المعلومات</h2><div class="clues">${w.item.clues.slice(0,w.revealed).map((c,i)=>`<div>🔎 ${i+1}. ${c}</div>`).join('')}</div>${renderAnswers(w.opts,w.correct)}${w.revealed<w.item.clues.length?`<button class="secondary clue-btn" onclick="moreClue()">💡 تلميح إضافي (-45)</button>`:''}</div>`}
window.moreClue=()=>{if(!state.who||state.locked)return;if(state.who.revealed<state.who.item.clues.length){state.who.revealed++;renderWho()}};

function budgetSetup(){clearTimer();nav(false);app.innerHTML=`${head('💰 تحدي الميزانية','مزاد 11 مركزًا · الميزانية بالمليون يورو')}<div class="setup-card"><label class="setting">اللاعب الأول<input id="bn1" class="input" value="عم عمرو"></label><label class="setting">اللاعب الثاني<input id="bn2" class="input" value="اللاعب 2"></label><div class="notice">💶 الميزانية الحالية: <b>${Number(s.budget)||750} M€</b> لكل لاعب · 🛒 الحد الأقصى للمزادات: <b>${Number(s.buyLimit)||6}</b></div><button class="primary" onclick="startBudgetGame()">🔨 ابدأ المزاد</button><button class="secondary" onclick="modes()">رجوع</button></div>`}
window.startBudgetGame=()=>{const n1=document.querySelector('#bn1')?.value.trim()||'اللاعب 1',n2=document.querySelector('#bn2')?.value.trim()||'اللاعب 2';if(n1===n2){alert('اختار اسمين مختلفين');return}const budget=Math.max(100,Number(s.budget)||750),limit=Math.max(1,Math.min(11,Number(s.buyLimit)||6));state.mode='budget';state.auction={players:[{name:n1,budget,team:[],bought:0},{name:n2,budget,team:[],bought:0}],slot:0,limit,history:[]};budgetRound()};
const auctionPos=['GK','RB','CB1','CB2','LB','DM','CM','AM','RW','LW','ST'];
function auctionCandidates(pos){const key=pos.replace(/\d/g,'');let pool=(A.auctionPool||[]).filter(x=>x.pos===key);if(pool.length<2)pool=A.auctionPool||[];return shuffle(pool).slice(0,Math.min(5,pool.length))}
function budgetRound(){const au=state.auction;if(!au)return;if(au.slot>=auctionPos.length)return budgetFinish();const pos=auctionPos[au.slot],cand=auctionCandidates(pos);const star=cand[0],free=cand.find(x=>x.name!==star.name)||cand[1]||star;au.current={pos,star,free};app.innerHTML=`${head('💰 تحدي الميزانية والمزاد',`المركز ${au.slot+1}/11 · ${pos} · كل الأرقام بالمليون يورو`)}<div class="budget-top">${au.players.map((p,i)=>`<div><b>${esc(p.name)}</b><span>💶 ${p.budget}M€</span><small>🛒 ${p.bought}/${au.limit} مزادات</small></div>`).join('')}</div><div class="auction-arena"><div class="auction-player"><div class="auction-badge">🔨 لاعب المزاد</div>${mediaCard(star.name,'صورة اللاعب عند توفر الإنترنت')}<h2>${star.name}</h2><p>⭐ تقييم المزاد: ${star.rating} · 💶 قيمة مرجعية: ${star.value||'—'}M€</p><strong>🔥 أعلى عرض يفوز</strong></div><div class="free-player mystery"><span>🎁 اللاعب المجاني</span><b>❓ مخفي حتى نهاية المزاد</b><small>المفاجأة قد تكون أقوى أو أضعف!</small></div></div><div class="bid-grid">${au.players.map((p,i)=>`<label>${esc(p.name)}<input id="bid${i}" type="number" min="0" max="${p.budget}" value="0" placeholder="عرضك بالمليون €"><small>${p.bought>=au.limit?'وصل حد الشراء — عرضه يجب أن يكون 0':'ميزانيتك: '+p.budget+'M€'}</small></label>`).join('')}</div><button class="primary" onclick="resolveBid()">🔨 حسم المزاد</button><div class="notice">🤫 لن تعرف اللاعب المجاني قبل حسم المزاد. بعد الحسم سيظهر لمن خسر المزاد مجانًا، وقد يقلب النتيجة!</div>`;const im=app.querySelector('img[data-media]');if(im)wikiImage(star.name,im)}
window.resolveBid=()=>{const au=state.auction;if(!au||state.locked)return;let bids=au.players.map((p,i)=>Math.max(0,Math.min(p.budget,Number(document.querySelector('#bid'+i)?.value)||0)));const eligible=au.players.map(p=>p.bought<au.limit);au.players.forEach((p,i)=>{if(!eligible[i])bids[i]=0});let winner;if(!eligible[0]&&!eligible[1])winner=Math.random()<.5?0:1;else if(eligible[0]&&!eligible[1])winner=0;else if(!eligible[0]&&eligible[1])winner=1;else if(bids[0]===bids[1])winner=Math.random()<.5?0:1;else winner=bids[0]>bids[1]?0:1;const loser=1-winner,{star,free,pos}=au.current,price=eligible[winner]?bids[winner]:0,paidPurchase=eligible[winner]&&price>0;au.players[winner].budget-=price;if(paidPurchase)au.players[winner].bought++;au.players[winner].team.push({...star,slot:pos,paid:price});au.players[loser].team.push({...free,slot:pos,paid:0});au.history.push({pos,winner,price,star:star.name,free:free.name});state.locked=true;correctSound();app.innerHTML+=`<div class="auction-result good">🔨 ${esc(au.players[winner].name)} حصل على <b>${star.name}</b> مقابل 💶 ${price}M€.<br>🎁 والمفاجأة: ${esc(au.players[loser].name)} حصل مجانًا على <b>${free.name}</b> ⭐${free.rating}!</div>`;setTimeout(()=>{state.locked=false;au.slot++;budgetRound()},1450)};
function budgetFinish(){const au=state.auction;const calc=p=>({strength:p.team.reduce((a,x)=>a+Number(x.rating||0),0),money:p.budget});const a=calc(au.players[0]),b=calc(au.players[1]);const final=x=>x.strength+(x.money/(Number(s.budget)||750))*35;const fs=[final(a),final(b)],win=fs[0]===fs[1]?-1:(fs[0]>fs[1]?0:1);if(win>=0)s.budgetWins=(s.budgetWins||0)+1;s.games++;trackGame();save();app.innerHTML=`${head('🏆 نتيجة تحدي الميزانية','قوة التشكيلة + قيمة الميزانية المتبقية')}<div class="budget-final">${au.players.map((p,i)=>{const c=calc(p);return `<div class="squad-card ${i===win?'winner':''}"><h2>${i===win?'👑 ':''}${esc(p.name)}</h2><div class="squad-list">${p.team.map(x=>`<span><b>${x.slot}</b> ${x.name}<em>⭐${x.rating} · 💶${x.paid}M€</em></span>`).join('')}</div><p>⭐ قوة التشكيلة: <b>${c.strength}</b></p><p>💶 المتبقي: <b>${c.money}M€</b></p><p>📊 التقييم النهائي: <b>${fs[i].toFixed(1)}</b></p></div>`}).join('')}</div><div class="result"><h1>${win<0?'🤝 تعادل!':'🏆 الفائز: '+esc(au.players[win].name)}</h1><button class="primary" onclick="start('budget')">إعادة التحدي 🔁</button></div>`}

function versusStore(){if(!s.versus)s.versus={};return s.versus}
function versus(){clearTimer();nav(false);app.innerHTML=`${head('⚔️ VERSUS','مواجهة مباشرة · 10 أسئلة · سجل دائم')}<div class="setup-card"><label class="setting">اللاعب الأول<input id="vp1" class="input" value="عم عمرو"></label><label class="setting">اللاعب الثاني<input id="vp2" class="input" value="اللاعب 2"></label><div class="notice">🔥 كل إجابة تحسب للاعب صاحب الدور، ثم ينتقل الدور تلقائيًا.</div><button class="primary" onclick="startVersusGame()">⚔️ ابدأ المواجهة</button><button class="secondary" onclick="versusStats()">📊 السجل</button></div>`}
window.startVersusGame=()=>{const a=document.querySelector('#vp1')?.value.trim()||'اللاعب 1',b=document.querySelector('#vp2')?.value.trim()||'اللاعب 2';if(a===b){alert('اختار اسمين مختلفين');return}state.mode='versus';state.versus={names:[a,b],turn:0,score:[0,0],q:0,total:Math.min(Number(s.rounds)||10,30)};versusQuestion()};
function versusQuestion(){const v=state.versus;if(v.q>=v.total)return versusFinish();const pool=(A.q||[]).filter(q=>q&&q[1]?.length>=4);const q=nextUnique('versusQ',pool);if(!q)return versusFinish();v.q++;v.correct=q[2];state.current={correct:q[2],next:()=>{const ok=state.lastAnswerOk===true;if(ok)v.score[v.turn]+=basePoints();v.turn=1-v.turn;versusQuestion()},points:basePoints()};app.innerHTML=`${head('⚔️ VERSUS',`${esc(v.names[0])} VS ${esc(v.names[1])} · سؤال ${v.q}/${v.total}`)}<div class="versus-score"><div class="${v.turn===0?'active':''}">${esc(v.names[0])}<b>${v.score[0]}</b></div><span>VS</span><div class="${v.turn===1?'active':''}">${esc(v.names[1])}<b>${v.score[1]}</b></div></div><div class="qbox"><span class="timer">${s.seconds||cfg().seconds}</span><span class="tag">دور: ${esc(v.names[v.turn])}</span><h2>${q[0]}</h2>${renderAnswers(q[1],q[2])}</div>`;startTimer(s.seconds||cfg().seconds,()=>{wrongSound();v.turn=1-v.turn;versusQuestion()})}
const oldAnswer=window.answer;window.answer=function(i){if(state.mode==='survival'){if(state.locked||!state.current)return;const ok=i===state.current.correct,pts=state.current.points||100;clearTimer();s.totalAnswered++;trackAnswer(ok);if(ok){state.score+=pts;s.totalCorrect++;state.streak++;s.streak=Math.max(s.streak||0,state.streak);save();return feedback(true,i,state.current.correct,state.survivalNext,pts,'🔥 استمر!')}state.streak=0;save();state.locked=true;document.querySelectorAll('.ans').forEach(b=>b.disabled=true);const btns=[...document.querySelectorAll('.ans')];if(btns[i])btns[i].classList.add('no');if(btns[state.current.correct])btns[state.current.correct].classList.add('ok');wrongSound();const box=document.querySelector('.feedback');if(box){box.className='feedback bad';box.innerHTML=`💥 انتهى التحدي<br>الإجابة الصحيحة: <b>${btns[state.current.correct]?.textContent||'—'}</b>`}setTimeout(()=>{state.locked=false;finish('انتهى تحدي البقاء')},1150);return}if(state.mode!=='versus')return oldAnswer(i);if(state.locked)return;const v=state.versus,ok=i===state.current.correct;clearTimer();state.locked=true;document.querySelectorAll('.ans').forEach(b=>b.disabled=true);if(ok){v.score[v.turn]+=basePoints();correctSound();}else{wrongSound();}const btns=[...document.querySelectorAll('.ans')];if(btns[i])btns[i].classList.add(ok?'ok':'no');if(btns[v.correct])btns[v.correct].classList.add('ok');setTimeout(()=>{state.locked=false;v.turn=1-v.turn;versusQuestion()},ok?450:1050)}
function versusFinish(){const v=state.versus,store=versusStore(),key=[v.names[0],v.names[1]].sort().join('|||');if(!store[key])store[key]={a:v.names[0],b:v.names[1],games:0,wins:[0,0],losses:[0,0],points:[0,0]};const rec=store[key];rec.games++;rec.points[0]+=v.score[0];rec.points[1]+=v.score[1];if(v.score[0]===v.score[1]){}else{const w=v.score[0]>v.score[1]?0:1;rec.wins[w]++;rec.losses[1-w]++;}save();app.innerHTML=`${head('📊 نتيجة VERSUS',`${esc(v.names[0])} VS ${esc(v.names[1])}`)}<div class="versus-final"><h1>${v.score[0]===v.score[1]?'🤝 تعادل!':'🏆 '+esc(v.names[v.score[0]>v.score[1]?0:1])}</h1><div><b>${esc(v.names[0])}</b> ${v.score[0]} — ${v.score[1]} <b>${esc(v.names[1])}</b></div></div><button class="primary" onclick="versusStats()">📊 إحصائيات المواجهة</button><button class="secondary" onclick="versus()">إعادة المواجهة 🔁</button>`}
function versusStats(){const store=versusStore(),rows=Object.values(store),rank={};rows.forEach(r=>{[0,1].forEach(i=>{const n=r[i?'b':'a'];rank[n]??={name:n,w:0,l:0,p:0,g:0};rank[n].w+=r.wins[i];rank[n].l+=r.losses[i];rank[n].p+=r.points[i];rank[n].g+=r.games})});const leaderboard=Object.values(rank).sort((a,b)=>b.w-a.w||b.p-a.p);app.innerHTML=`${head('⚔️ VERSUS','سجل المواجهات + ترتيب اللاعبين')}<h2>🏆 الترتيب العام</h2><div class="versus-ranking">${leaderboard.length?leaderboard.map((r,i)=>`<div><b>#${i+1} ${esc(r.name)}</b><span>🏆 ${r.w} فوز · ❌ ${r.l} خسارة · ⭐ ${r.p} نقطة · 🎮 ${r.g} مباريات</span></div>`).join(''):'لا يوجد ترتيب بعد'}</div><h2>📊 المواجهات المباشرة</h2><div class="versus-table">${rows.length?rows.map(r=>{const total=Math.max(1,r.wins[0]+r.wins[1]+(r.games-r.wins[0]-r.wins[1]));const p0=Math.round(r.wins[0]/total*100),p1=Math.round(r.wins[1]/total*100);return `<div class="versus-row"><h3>${esc(r.a)} <span>VS</span> ${esc(r.b)}</h3><p>🏆 ${esc(r.a)}: ${r.wins[0]} فوز · ${r.losses[0]} خسارة · نسبة الفوز ${p0}%</p><p>🏆 ${esc(r.b)}: ${r.wins[1]} فوز · ${r.losses[1]} خسارة · نسبة الفوز ${p1}%</p><p>🎮 ${r.games} مواجهات · ⭐ النقاط ${r.points[0]} — ${r.points[1]}</p></div>`}).join(''):'لا توجد مواجهات مسجلة بعد.'}</div>`}

function achievements(){const acc=s.totalAnswered?Math.round(s.totalCorrect/s.totalAnswered*100):0;const defs=[['🎯','أول خطوة',s.totalCorrect>=1,'حقق أول إجابة صحيحة'],['🔥','سلسلة نار',s.streak>=10,'حقق سلسلة 10 إجابات صحيحة'],['💯','المئوية',s.totalCorrect>=100,'100 إجابة صحيحة'],['🧠','خبير كروي',s.totalCorrect>=500,'500 إجابة صحيحة'],['🏆','محترف الجولات',s.games>=25,'العب 25 جولة'],['🎯','قناص',acc>=80&&s.totalAnswered>=50,'دقة 80% بعد 50 سؤال'],['💰','ملك المزاد',s.budgetWins>=3,'فوز 3 مرات في تحدي الميزانية'],['🕵️','المحقق',s.whoWins>=20,'20 إجابة صحيحة في من أنا؟'],['⭐','أسطورة 90',level()>=10,'الوصول للمستوى 10']];return defs}
function stats(){nav(true);const acc=s.totalAnswered?Math.round(s.totalCorrect/s.totalAnswered*100):0,d=dailyState(),defs=achievements(),unlocked=defs.filter(x=>x[2]).length;app.innerHTML=`${head('🏆 الإنجازات والمهام','تقدمك محفوظ على الجهاز')}<div class="stats"><div class="stat"><b>Lv.${level()}</b>المستوى</div><div class="stat"><b>${s.xp||0}</b>XP</div><div class="stat"><b>${acc}%</b>الدقة</div><div class="stat"><b>${unlocked}/${defs.length}</b>إنجازات</div></div><h2>🏅 أفضل الإنجازات</h2><div class="achievement-grid">${defs.map(x=>`<div class="achievement-card ${x[2]?'':'locked'}"><span>${x[0]}</span><b>${x[1]}</b><small>${x[3]}</small><em>${x[2]?'✅ مفتوح':'🔒 مقفول'}</em></div>`).join('')}</div><h2>📅 مهام اليوم</h2><div class="tasks"><div>${d.answered>=10?'✅':'⬜'} أجب عن 10 أسئلة <b>${Math.min(d.answered,10)}/10</b></div><div>${d.correct>=7?'✅':'⬜'} حقق 7 إجابات صحيحة <b>${Math.min(d.correct,7)}/7</b></div><div>${d.games>=2?'✅':'⬜'} العب جولتين <b>${Math.min(d.games,2)}/2</b></div></div><div class="notice">🔥 أفضل سلسلة: ${s.streak||0} · 💰 انتصارات المزاد: ${s.budgetWins||0} · 🎯 إجابات صحيحة: ${s.totalCorrect||0}</div>`}
function modes(){nav(true);const cats=[['🧠','كويز 90','بنك أسئلة ضخم ومتجدد','quiz'],['🕵️','من أنا؟','اكشف التلميحات حتى تعرف اللاعب','who'],['💰','تحدي الميزانية','مزاد 11 مركزًا وتشكيلتان','budget'],['👤','خمن اللاعب','صورة + تلميحات','player'],['🌍','الجنسيات','اعرف بلد النجم','nation'],['🏟️','الأندية','خمن النادي الحالي','club'],['🧩','خمن الفريق من الجنسيات','تشكيلة XI كاملة بالجنسيات','teamNat'],['🛡️','خمن المنتخب من الشعارات','تشكيلة XI كاملة بشعارات الأندية','teamClub'],['📋','تحدي التشكيلة XI','خمن الفريق من جنسيات 11 لاعبًا','lineup'],['🧭','مسار اللاعب','اعرف اللاعب من مسيرته','career'],['✖️','هل لعب هنا؟','اختبر مسيرة النجوم','cross'],['💸','سوق الانتقالات','خمن سعر وقيمة الصفقة','price'],['🎯','القيمة الأقرب','خمن مبلغ الصفقة','exact'],['⚡','Blitz 60','أكبر عدد من الإجابات','blitz'],['🔥','البقاء','خطأ واحد ينهي السلسلة','survival'],['📈','أعلى/أقل','قارن أعمار اللاعبين','higher'],['👥','جماعي محلي','2–8 لاعبين','local'],['🖼️','خمن الصورة','صور كاملة مع بدائل ذكية','face'],['📅','تحدي اليوم','جولة يومية مختلفة','daily'],['⚔️','VERSUS','مواجهات مباشرة وسجل تاريخي بين لاعبين','versus']];app.innerHTML=`${head('⚽ كل التحديات',`موسم ${A.meta?.season||'2026/27'} · آخر مزامنة ${A.meta?.updated||'10 سبتمبر 2026'}`)}<div class="mode-toolbar"><span class="tag">${s.diff}</span><span class="tag">${s.rounds} سؤال</span><span class="tag">⭐ ${s.questionPoints} نقطة/سؤال</span><span class="tag">${A.players?.length||0} لاعب + بنك موسع</span></div><div class="mode-list">${cats.map(c=>`<button class="mode-card" onclick="start('${c[3]}')"><div style="font-size:31px">${c[0]}</div><h3>${c[1]}</h3><p>${c[2]}</p></button>`).join('')}</div>`}
function home(){nav(true);const acc=s.totalAnswered?Math.round(s.totalCorrect/s.totalAnswered*100):0;app.innerHTML=`<section class="hero"><div><span class="pill">⚡ 90 دقيقة FINAL</span><h1>أسئلة. مزادات. تشكيلات. <em>تحدي كروي كامل.</em></h1><p>نسخة أكبر: من أنا؟، مزاد الميزانية، جوكر 50/50، مضاعفة، تخطي، إنجازات ومهام يومية، صور وشعارات بتحميل احتياطي ذكي.</p><button class="primary" onclick="modes()">ابدأ اللعب 🔥</button></div><div class="ball">⚽</div></section><div class="stats"><div class="stat"><b>${s.xp||0}</b>XP</div><div class="stat"><b>${s.best||0}</b>أفضل نتيجة</div><div class="stat"><b>${s.games||0}</b>جولات</div><div class="stat"><b>${acc}%</b>دقة</div></div><div class="live-box">🟢 <b>الموسم: ${A.meta?.season||'2026/27'}</b><br><span>آخر تحديث تحريري: ${A.meta?.updated||'10 سبتمبر 2026'}</span><br><small>الصور والشعارات تُجلب من مصادر موسوعية عند الاتصال، ومع فشل الشبكة يظهر بديل واضح بدل مساحة فارغة.</small></div><div class="feature-strip"><span>✂️ 50/50</span><span>×2 نقاط</span><span>⏭️ تخطي</span><span>💰 مزاد</span><span>🕵️ من أنا؟</span></div><h2>🏆 تقدمك</h2><div class="achievement"><span class="icon">🎯</span><div><b>${s.totalCorrect||0} إجابة صحيحة</b><div class="muted">من ${s.totalAnswered||0} سؤال</div></div></div><div class="achievement"><span class="icon">🔥</span><div><b>أفضل سلسلة ${s.streak||0}</b><div class="muted">المستوى الحالي ${level()}</div></div></div><div class="home-credit">By : <b>Amr Fares</b></div>`}
function settings(){nav(true);app.innerHTML=`${head('⚙️ الإعدادات','تحكم كامل في طريقة اللعب')}<label class="setting">اسم اللاعب<input id="nm" class="input" value="${esc(s.name)}" placeholder="اسمك"></label><label class="setting">اللون الأساسي<input id="ac" type="color" value="${s.ac}"></label><label class="setting">لون الخلفية<input id="bg" type="color" value="${s.bg}"></label><label class="setting">الصعوبة<select id="df">${Object.keys(diffCfg).map(x=>`<option ${s.diff===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting">عدد الأسئلة<select id="rd">${[5,10,15,20,30,50,75,100].map(x=>`<option ${Number(s.rounds)===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting">نقاط الإجابة الصحيحة<select id="qp">${[50,75,100,120,150,200,250,300,500,1000].map(x=>`<option value="${x}" ${Number(s.questionPoints)===x?'selected':''}>${x} نقطة</option>`).join('')}</select></label><label class="setting">وقت السؤال<select id="tm">${[5,10,15,20,30,45,60,90].map(x=>`<option ${Number(s.seconds)===x?'selected':''}>${x} ثانية</option>`).join('')}</select><div class="setting-group"><h3>💰 إعدادات تحدي الميزانية</h3><label class="setting">ميزانية كل لاعب<select id="bd">${[300,500,750,1000,1500,2000].map(x=>`<option value="${x}" ${Number(s.budget)===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting">أقصى عدد مزادات يمكن لكل لاعب شراؤها<select id="bl">${[3,4,5,6,7,8,9,10,11].map(x=>`<option ${Number(s.buyLimit)===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="setting toggle">الصوت <input id="snd" type="checkbox" ${s.sound?'checked':''}></label><label class="setting toggle">الحركة والمؤثرات <input id="anm" type="checkbox" ${s.anim?'checked':''}></label><button class="primary" onclick="applySet()">حفظ الإعدادات 💾</button><button onclick="versusStats()" class="secondary">⚔️ إحصائيات VERSUS</button><button onclick="resetProgress()" class="danger-btn">مسح التقدم</button>`}
window.applySet=()=>{s.name=document.querySelector('#nm').value;s.ac=document.querySelector('#ac').value;s.bg=document.querySelector('#bg').value;s.diff=document.querySelector('#df').value;s.rounds=Number(document.querySelector('#rd').value);s.questionPoints=Number(document.querySelector('#qp').value);s.seconds=Number(document.querySelector('#tm').value.split(' ')[0]);s.budget=Number(document.querySelector('#bd').value);s.buyLimit=Number(document.querySelector('#bl').value);s.sound=document.querySelector('#snd').checked;s.anim=document.querySelector('#anm').checked;save();applyTheme();settings()};window.resetProgress=()=>{if(confirm('متأكد من مسح كل التقدم؟')){try{localStorage.removeItem('90dq')}catch(e){}location.reload()}};
window.start=m=>{setup(m);if(m==='quiz')questionQuiz();else if(m==='player')playerQuestion();else if(m==='nation')attrQuestion(1,'ما جنسية اللاعب؟');else if(m==='club')attrQuestion(2,'ما النادي الحالي للاعب؟');else if(m==='teamNat')teamFromNationalities();else if(m==='teamClub')nationalFromClubs();else if(m==='lineup')lineup();else if(m==='career')careerQuestion();else if(m==='cross')crossQuestion();else if(m==='price')transferMode(false);else if(m==='exact')transferMode(true);else if(m==='blitz')blitz();else if(m==='survival')survival();else if(m==='higher')higher();else if(m==='local')local();else if(m==='face')face();else if(m==='daily')daily();else if(m==='who')whoAmI();else if(m==='budget')budgetSetup();else if(m==='versus')versus()};
window.home=home;window.modes=modes;window.stats=stats;window.settings=settings;document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>({home,modes,stats,settings}[x.dataset.page])());document.querySelector('#set').onclick=settings;home();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
// Public handlers for inline buttons (required by the static HTML UI)
window.localRound=localRound;
window.localAnswer=localAnswer;
window.local=local;
window.versus=versus;
window.versusStats=versusStats;
})();
